485	// ---------- nec_1099_export_record ----------
486	
487	export interface Nec1099ExportRecordArgs {
488	  studioId: string;
489	  year: number;
490	  artistId: string;
491	  totalPaidCents: CentsAmount;
492	  federalIdLast4: string | null;
493	  stateIdLast4: string | null;
