498	export type Nec1099ExportRecordResult = { id: string };
499	
500	// ---------- apply_deposit_to_session (S16) ----------
501	
502	/**
503	 * SAGA STEP 1: Atomically reserve a deposit pool drawdown for an upcoming PaymentIntent.
504	 *
505	 * Behavior:
506	 *   1. SELECT FOR UPDATE on `projects.deposit_pool_cents_available`.
507	 *   2. Verify available >= draw_cents. RAISE EXCEPTION if not.
508	 *   3. Decrement available, increment applied.
509	 *   4. INSERT into `project_deposit_transactions` with status='pending_apply'.
510	 *   5. Return the transaction id.
511	 *
512	 * Caller flow: call this BEFORE stripe.paymentIntents.create(). Pass the returned
513	 * transaction_id in the PaymentIntent metadata. The webhook handler then calls:
514	 *   - confirm_deposit_application(txn_id) on payment_intent.succeeded
515	 *   - rollback_deposit_application(txn_id) on payment_intent.payment_failed | canceled
516	 *
517	 * If the caller fails to create the PaymentIntent, they MUST call rollback explicitly.
518	 * A reaper cron should sweep `pending_apply` rows older than 30 minutes and roll them back.
519	 */
520	export interface ApplyDepositToSessionArgs {
521	  projectId: string;
522	  sessionId: string;
523	  drawCents: CentsAmount;
524	  idempotencyKey: InkosIdempotencyKey;          // dedupe on PaymentIntent retries
525	}
526	export type ApplyDepositToSessionResult = {
527	  transaction_id: string;
528	  pool_in_cents: CentsAmount;
529	  pool_applied_cents: CentsAmount;
530	  pool_available_cents: CentsAmount;
531	};
532	
533	// ---------- confirm_deposit_application (S16) ----------
534	
535	/**
536	 * SAGA STEP 2 (success path): Mark a pending_apply transaction as applied.
537	 * Called from the webhook handler on payment_intent.succeeded.
538	 *
539	 * Idempotent — re-running on an already-confirmed txn is a no-op.
540	 * RAISE EXCEPTION if txn was already rolled_back or released.
541	 */
542	export interface ConfirmDepositApplicationArgs {
543	  transactionId: string;
544	  paymentIntentId: string;                      // for cross-reference
545	}
546	export type ConfirmDepositApplicationResult = {
547	  transaction_id: string;
548	  status: 'applied' | 'already_applied';
549	};
550	
551	// ---------- rollback_deposit_application (S16) ----------
552	
553	/**
554	 * SAGA STEP 2 (failure path): Roll back a pending_apply transaction.
555	 * Called from the webhook handler on payment_intent.payment_failed | canceled,
556	 * OR by the reaper cron after 30-min timeout.
557	 *
558	 * Behavior:
559	 *   1. SELECT FOR UPDATE on the txn + parent project.
560	 *   2. Re-increment available, decrement applied.
561	 *   3. Mark txn status='rolled_back', set rolled_back_at + reason.
562	 *
563	 * Idempotent — re-running on an already-rolled-back txn is a no-op.
564	 * RAISE EXCEPTION if txn is already 'applied' (cannot rollback a confirmed txn —
565	 * issue a refund instead via release_deposit_from_session).
566	 */
567	export interface RollbackDepositApplicationArgs {
568	  transactionId: string;
569	  reason: 'payment_failed' | 'payment_canceled' | 'reaper_timeout' | 'manual';
570	}
571	export type RollbackDepositApplicationResult = {
572	  transaction_id: string;
573	  status: 'rolled_back' | 'already_rolled_back';
574	  pool_available_cents: CentsAmount;
575	};
576	
577	// ---------- release_deposit_from_session (S16) ----------
578	
579	/**
580	 * Refund path: re-credit a previously-applied deposit drawdown back to the pool.
581	 *
582	 * Called from refund flow when the original session charge consumed pool funds.
583	 * Partial refunds are supported (release_cents <= original draw_cents).
584	 *
585	 * Behavior:
586	 *   1. SELECT FOR UPDATE on the txn + parent project.
587	 *   2. Verify txn status='applied' (cannot release pending/rolled_back).
588	 *   3. Verify release_cents <= (txn.draw_cents - already-released amount).
589	 *   4. Re-increment available, decrement applied (by release_cents).
590	 *   5. INSERT a child txn with kind='released', parent_transaction_id=txn_id.
591	 *
592	 * NOT idempotent on its own — caller passes a unique idempotency_key in args
593	 * to dedupe on Stripe webhook replay (charge.refunded fires multiple times).
594	 */
595	export interface ReleaseDepositFromSessionArgs {
596	  transactionId: string;                        // original applied txn
597	  releaseCents: CentsAmount;
598	  idempotencyKey: InkosIdempotencyKey;
599	  refundId: string;                             // Stripe refund_xxx for cross-reference
600	}
601	export type ReleaseDepositFromSessionResult = {
602	  release_transaction_id: string;
603	  pool_available_cents: CentsAmount;
604	  total_released_cents: CentsAmount;            // running total released against parent txn
605	};
606	
607	// ---------- studio_l2_payments_enabled (S15) ----------
608	
609	/**
610	 * Capability gate: returns true only if the studio has an active Stripe Connect
611	 * account with `charges_enabled` capability. Used by S16+ in-studio charge code
612	 * paths to refuse charges before the studio's KYC is complete.
613	 *
614	 * Called from: feature-gate layer + UI banner suppression on /dashboard.
615	 *
616	 * `reason` is populated only when `enabled=false`. Possible values:
617	 *   - 'no_connected_account'      — studio has not started Connect onboarding
618	 *   - 'onboarding_pending'        — account exists but KYC incomplete
619	 *   - 'onboarding_restricted'     — Stripe restricted the account (KYC docs needed)
620	 *   - 'onboarding_rejected'       — Stripe permanently rejected
621	 *   - 'charges_disabled'          — Stripe revoked charges capability
622	 */
623	export interface StudioL2PaymentsEnabledArgs {
624	  studioId: string;
625	}
626	export type StudioL2PaymentsEnabledResult = {
627	  enabled: boolean;
628	  reason: string | null;
629	  account_id: string | null;
630	  onboarding_status: ConnectedAccountOnboardingStatus | null;
631	};
632	
633	// ---------- artist_l2_payouts_enabled (S15) ----------
634	
635	/**
636	 * Capability gate for artists who opt into direct payouts.
637	 * Returns true only if the artist has their own active Stripe Connect account
638	 * with `payouts_enabled` AND `transfers` capabilities.
639	 *
640	 * If false, commission splits flow to the studio's connected account and the
641	 * studio pays the artist via existing payroll path (1099 or W-2).
642	 *
643	 * `reason` possible values:
644	 *   - 'self_payouts_disabled'     — artist hasn't opted in (`payouts_self_enabled=false`)
645	 *   - 'no_connected_account'      — opted in but no Stripe account created yet
646	 *   - 'onboarding_pending'        — account exists, KYC incomplete
647	 *   - 'onboarding_restricted'     — Stripe restricted
648	 *   - 'onboarding_rejected'       — permanently rejected
649	 *   - 'transfers_disabled'        — capability missing
650	 *   - 'payouts_disabled'          — capability missing
651	 */
652	export interface ArtistL2PayoutsEnabledArgs {
653	  artistId: string;
654	}
655	export type ArtistL2PayoutsEnabledResult = {
656	  enabled: boolean;
657	  reason: string | null;
658	  account_id: string | null;
659	  onboarding_status: ConnectedAccountOnboardingStatus | null;
660	};
661	
662	// =====================================================================
663	// PRESET SPLIT PERCENTAGES (locked defaults — overridable per studio)
664	// =====================================================================
665	
666	export const DEFAULT_COMMISSION_PCT = {
667	  RESIDENT_ESTABLISHED: 70,    // 70/30 in artist's favor
668	  RESIDENT_NEW: 60,            // 60/40
669	  RESIDENT_FULL_SUPPORT: 50,   // 50/50 when shop covers everything
670	  GUEST: 80,                   // 80/20 in guest's favor
671	  APPRENTICE: 50,              // 50/50 ramp
672	  BOOTH_RENTER: 100,           // booth renter keeps everything (rent invoiced separately)
673	} as const;
674	
675	// =====================================================================
676	// INVARIANTS — Sage scans verify these hold across the codebase
677	// =====================================================================
678	
679	/**
680	 * INVARIANT 1: All money is CentsAmount. Never `number` for money.
681	 * INVARIANT 2: Every Stripe call carries `metadata.inkos_idempotency_key`.
682	 * INVARIANT 3: Every webhook handler's first write is webhook_event_insert.
683	 * INVARIANT 4: `application_fee_amount` is set on every PaymentIntent (never undefined).
684	 * INVARIANT 5: Refunds always pass `reverse_transfer: true` AND `refund_application_fee: true`.
685	 * INVARIANT 6: `subscriptions` and `stripe_charges` are webhook-only writes from app code.
686	 * INVARIANT 7: Dodo (L1) and Stripe (L2) abstractions never share a module.
687	 * INVARIANT 8: Banker's rounding when computing splits to avoid systematic bias.
688	 */
689

