/**
 * RPC contract tests: apply_deposit_to_session
 *
 * Coverage (6 tests — DB-gated via describe.skipIf):
 *  1. Happy path: project with $400 pool, draw $200 → txn_id returned, pool decremented
 *  2. Idempotency: same idempotency_key → same txn_id, pool not double-decremented
 *  3. Insufficient pool: draw > available → RAISE EXCEPTION
 *  4. draw_cents=0 → RAISE EXCEPTION
 *  5. Project not found → RAISE EXCEPTION
 *  6. Concurrent draws: SELECT FOR UPDATE semantics — second draw fails if first depletes pool
 *
 * Per-test isolation: each test gets its own fresh studio (beforeEach/afterEach).
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  cents,
  type ApplyDepositToSessionArgs,
  type ApplyDepositToSessionResult,
  type InkosIdempotencyKey,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: apply_deposit_to_session', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string

  beforeEach(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
  })

  afterEach(async () => {
    await cleanupStudio(studioId)
  })

  // ---------------------------------------------------------------------------
  // Helper: insert a project with a deposit pool
  // ---------------------------------------------------------------------------
  async function insertProjectWithPool(opts: {
    poolInCents: number
    poolAppliedCents?: number
  }): Promise<string> {
    const projectId = randomUUID()
    const { error } = await sb.from('projects').insert({
      id: projectId,
      studio_id: studioId,
      name: `Test Project ${projectId.slice(0, 8)}`,
      deposit_pool_cents_in: opts.poolInCents,
      deposit_pool_cents_applied: opts.poolAppliedCents ?? 0,
      deposit_pool_cents_available: opts.poolInCents - (opts.poolAppliedCents ?? 0),
      status: 'active',
    })
    if (error) throw new Error(`insertProjectWithPool failed: ${error.message}`)
    return projectId
  }

  function makeIdempotencyKey(): InkosIdempotencyKey {
    return `inkos_apply_deposit_${randomUUID().replace(/-/g, '').slice(0, 32)}` as InkosIdempotencyKey
  }

  it('happy path — draws $200 from $400 pool, returns txn_id and correct pool state', async () => {
    const projectId = await insertProjectWithPool({ poolInCents: 40000 })
    const sessionId = randomUUID()

    const args: ApplyDepositToSessionArgs = {
      projectId,
      sessionId,
      drawCents: cents(20000),
      idempotencyKey: makeIdempotencyKey(),
    }

    const { data, error } = await sb.rpc(RPC.APPLY_DEPOSIT_TO_SESSION, {
      p_project_id: args.projectId,
      p_session_id: args.sessionId,
      p_draw_cents: args.drawCents,
      p_idempotency_key: args.idempotencyKey,
    })

    expect(error).toBeNull()
    const result = data as ApplyDepositToSessionResult
    expect(result.transaction_id).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/,
    )
    expect(result.pool_in_cents).toBe(40000)
    expect(result.pool_applied_cents).toBe(20000)
    expect(result.pool_available_cents).toBe(20000)
  })

  it('idempotency — same key returns same txn_id; pool not double-decremented', async () => {
    const projectId = await insertProjectWithPool({ poolInCents: 40000 })
    const sessionId = randomUUID()
    const idemKey = makeIdempotencyKey()

    const callArgs = {
      p_project_id: projectId,
      p_session_id: sessionId,
      p_draw_cents: cents(20000),
      p_idempotency_key: idemKey,
    }

    const { data: first, error: e1 } = await sb.rpc(RPC.APPLY_DEPOSIT_TO_SESSION, callArgs)
    expect(e1).toBeNull()
    const firstResult = first as ApplyDepositToSessionResult

    const { data: second, error: e2 } = await sb.rpc(RPC.APPLY_DEPOSIT_TO_SESSION, callArgs)
    expect(e2).toBeNull()
    const secondResult = second as ApplyDepositToSessionResult

    // Same transaction returned
    expect(secondResult.transaction_id).toBe(firstResult.transaction_id)
    // Pool only decremented once — available still 20000 not 0
    expect(secondResult.pool_available_cents).toBe(20000)
    expect(secondResult.pool_applied_cents).toBe(20000)
  })

  it('insufficient pool — draw > available raises exception', async () => {
    // Only $100 available
    const projectId = await insertProjectWithPool({ poolInCents: 10000 })
    const sessionId = randomUUID()

    const { error } = await sb.rpc(RPC.APPLY_DEPOSIT_TO_SESSION, {
      p_project_id: projectId,
      p_session_id: sessionId,
      p_draw_cents: 20000, // $200 requested vs $100 available
      p_idempotency_key: makeIdempotencyKey(),
    })

    expect(error).not.toBeNull()
    // Should be a Postgres RAISE EXCEPTION — error code P0001 or message about insufficient
    expect(
      error?.code === 'P0001' ||
      error?.message?.toLowerCase().includes('insufficient') ||
      error?.message?.toLowerCase().includes('pool') ||
      error?.message?.toLowerCase().includes('available'),
    ).toBe(true)
  })

  it('draw_cents=0 raises exception', async () => {
    const projectId = await insertProjectWithPool({ poolInCents: 40000 })
    const sessionId = randomUUID()

    const { error } = await sb.rpc(RPC.APPLY_DEPOSIT_TO_SESSION, {
      p_project_id: projectId,
      p_session_id: sessionId,
      p_draw_cents: 0,
      p_idempotency_key: makeIdempotencyKey(),
    })

    expect(error).not.toBeNull()
    expect(
      error?.code === 'P0001' ||
      error?.message?.toLowerCase().includes('must be') ||
      error?.message?.toLowerCase().includes('positive') ||
      error?.message?.toLowerCase().includes('zero'),
    ).toBe(true)
  })

  it('project not found raises exception', async () => {
    const { error } = await sb.rpc(RPC.APPLY_DEPOSIT_TO_SESSION, {
      p_project_id: randomUUID(), // non-existent project
      p_session_id: randomUUID(),
      p_draw_cents: 10000,
      p_idempotency_key: makeIdempotencyKey(),
    })

    expect(error).not.toBeNull()
    // Either FK violation or RAISE EXCEPTION for not found
    expect(error?.message).toBeTruthy()
  })

  it('concurrent draws — second draw fails when pool is depleted by first', async () => {
    // Pool of exactly $200 — first draw of $200 exhausts it
    const projectId = await insertProjectWithPool({ poolInCents: 20000 })
    const sessionId1 = randomUUID()
    const sessionId2 = randomUUID()

    // First draw — takes the full pool
    const { data: first, error: e1 } = await sb.rpc(RPC.APPLY_DEPOSIT_TO_SESSION, {
      p_project_id: projectId,
      p_session_id: sessionId1,
      p_draw_cents: 20000,
      p_idempotency_key: makeIdempotencyKey(),
    })
    expect(e1).toBeNull()
    const firstResult = first as ApplyDepositToSessionResult
    expect(firstResult.pool_available_cents).toBe(0)

    // Second draw — pool is now 0, must fail
    const { error: e2 } = await sb.rpc(RPC.APPLY_DEPOSIT_TO_SESSION, {
      p_project_id: projectId,
      p_session_id: sessionId2,
      p_draw_cents: 20000, // same amount, but pool is exhausted
      p_idempotency_key: makeIdempotencyKey(),
    })

    expect(e2).not.toBeNull()
    expect(
      e2?.code === 'P0001' ||
      e2?.message?.toLowerCase().includes('insufficient') ||
      e2?.message?.toLowerCase().includes('pool'),
    ).toBe(true)
  })
})

/**
 * RPC contract tests: confirm_deposit_application
 *
 * Coverage (5 tests — DB-gated via describe.skipIf):
 *  1. Happy path: pending_apply → applied, confirmed_at populated, payment_intent_id stored
 *  2. Idempotency: re-confirm already-applied → status='already_applied', no error
 *  3. Rolled-back txn → RAISE EXCEPTION
 *  4. Released txn → RAISE EXCEPTION
 *  5. Missing txn → RAISE EXCEPTION
 *
 * Per-test isolation: each test creates its own studio and project.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  cents,
  type ConfirmDepositApplicationArgs,
  type ConfirmDepositApplicationResult,
  type InkosIdempotencyKey,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: confirm_deposit_application', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string

  beforeEach(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
  })

  afterEach(async () => {
    await cleanupStudio(studioId)
  })

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------

  async function insertProjectWithPool(poolInCents: number): Promise<string> {
    const projectId = randomUUID()
    const { error } = await sb.from('projects').insert({
      id: projectId,
      studio_id: studioId,
      name: `Test Project ${projectId.slice(0, 8)}`,
      deposit_pool_cents_in: poolInCents,
      deposit_pool_cents_applied: 0,
      deposit_pool_cents_available: poolInCents,
      status: 'active',
    })
    if (error) throw new Error(`insertProjectWithPool failed: ${error.message}`)
    return projectId
  }

  function makeIdempotencyKey(): InkosIdempotencyKey {
    return `inkos_apply_deposit_${randomUUID().replace(/-/g, '').slice(0, 32)}` as InkosIdempotencyKey
  }

  /** Creates a pending_apply transaction by calling apply_deposit_to_session. */
  async function createPendingApplyTxn(
    projectId: string,
    drawCents: number = 20000,
  ): Promise<string> {
    const { data, error } = await sb.rpc(RPC.APPLY_DEPOSIT_TO_SESSION, {
      p_project_id: projectId,
      p_session_id: randomUUID(),
      p_draw_cents: drawCents,
      p_idempotency_key: makeIdempotencyKey(),
    })
    if (error) throw new Error(`createPendingApplyTxn failed: ${error.message}`)
    const result = data as { transaction_id: string }
    return result.transaction_id
  }

  /** Force-update a txn status directly (for test setup of non-happy states). */
  async function forceTxnStatus(txnId: string, status: string): Promise<void> {
    const { error } = await sb
      .from('project_deposit_transactions')
      .update({ status, rolled_back_at: status === 'rolled_back' ? new Date().toISOString() : null })
      .eq('id', txnId)
    if (error) throw new Error(`forceTxnStatus failed: ${error.message}`)
  }

  it('happy path — pending_apply transitions to applied with confirmed_at and payment_intent_id', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await createPendingApplyTxn(projectId)
    const piId = `pi_test_${randomUUID().replace(/-/g, '').slice(0, 24)}`

    const args: ConfirmDepositApplicationArgs = {
      transactionId: txnId,
      paymentIntentId: piId,
    }

    const { data, error } = await sb.rpc(RPC.CONFIRM_DEPOSIT_APPLICATION, {
      p_transaction_id: args.transactionId,
      p_payment_intent_id: args.paymentIntentId,
    })

    expect(error).toBeNull()
    const result = data as ConfirmDepositApplicationResult
    expect(result.transaction_id).toBe(txnId)
    expect(result.status).toBe('applied')

    // Verify DB row was updated
    const { data: row } = await sb
      .from('project_deposit_transactions')
      .select('status, confirmed_at, payment_intent_id')
      .eq('id', txnId)
      .single()

    expect(row?.status).toBe('applied')
    expect(row?.confirmed_at).toBeTruthy()
    expect(row?.payment_intent_id).toBe(piId)
  })

  it('idempotency — re-confirming an already-applied txn returns status=already_applied without error', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await createPendingApplyTxn(projectId)
    const piId = `pi_test_${randomUUID().replace(/-/g, '').slice(0, 24)}`

    const callArgs = {
      p_transaction_id: txnId,
      p_payment_intent_id: piId,
    }

    const { error: e1 } = await sb.rpc(RPC.CONFIRM_DEPOSIT_APPLICATION, callArgs)
    expect(e1).toBeNull()

    // Second call — already confirmed
    const { data: second, error: e2 } = await sb.rpc(RPC.CONFIRM_DEPOSIT_APPLICATION, callArgs)
    expect(e2).toBeNull()
    const result = second as ConfirmDepositApplicationResult
    expect(result.status).toBe('already_applied')
    expect(result.transaction_id).toBe(txnId)
  })

  it('rolled_back txn — confirm raises exception', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await createPendingApplyTxn(projectId)

    // Roll it back first
    const { error: rbErr } = await sb.rpc(RPC.ROLLBACK_DEPOSIT_APPLICATION, {
      p_transaction_id: txnId,
      p_reason: 'payment_canceled',
    })
    expect(rbErr).toBeNull()

    // Now try to confirm the rolled-back txn
    const { error } = await sb.rpc(RPC.CONFIRM_DEPOSIT_APPLICATION, {
      p_transaction_id: txnId,
      p_payment_intent_id: `pi_test_${randomUUID().replace(/-/g, '').slice(0, 24)}`,
    })

    expect(error).not.toBeNull()
    expect(
      error?.code === 'P0001' ||
      error?.message?.toLowerCase().includes('rolled') ||
      error?.message?.toLowerCase().includes('cannot confirm'),
    ).toBe(true)
  })

  it('released txn — confirm raises exception', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await createPendingApplyTxn(projectId)
    const piId = `pi_test_${randomUUID().replace(/-/g, '').slice(0, 24)}`

    // Confirm it first
    await sb.rpc(RPC.CONFIRM_DEPOSIT_APPLICATION, {
      p_transaction_id: txnId,
      p_payment_intent_id: piId,
    })

    // Release it (partial is fine)
    await sb.rpc(RPC.RELEASE_DEPOSIT_FROM_SESSION, {
      p_transaction_id: txnId,
      p_release_cents: 20000,
      p_idempotency_key: `inkos_release_${randomUUID().replace(/-/g, '').slice(0, 32)}` as InkosIdempotencyKey,
      p_refund_id: `re_test_${randomUUID().replace(/-/g, '').slice(0, 24)}`,
    })

    // Force status to released via direct update (the release flow creates a child txn,
    // parent may still be 'applied' — test the direct released status path)
    await forceTxnStatus(txnId, 'released')

    // Now try to confirm a released txn
    const { error } = await sb.rpc(RPC.CONFIRM_DEPOSIT_APPLICATION, {
      p_transaction_id: txnId,
      p_payment_intent_id: `pi_test_${randomUUID().replace(/-/g, '').slice(0, 24)}`,
    })

    expect(error).not.toBeNull()
  })

  it('missing txn — confirm raises exception', async () => {
    const { error } = await sb.rpc(RPC.CONFIRM_DEPOSIT_APPLICATION, {
      p_transaction_id: randomUUID(), // non-existent
      p_payment_intent_id: `pi_test_${randomUUID().replace(/-/g, '').slice(0, 24)}`,
    })

    expect(error).not.toBeNull()
    expect(error?.message).toBeTruthy()
  })
})

/**
 * RPC contract tests: rollback_deposit_application
 *
 * Coverage (6 tests — DB-gated via describe.skipIf):
 *  1. Happy path (payment_failed): pending_apply → rolled_back, pool re-incremented
 *  2. Happy path (payment_canceled): same
 *  3. Happy path (reaper_timeout): same
 *  4. Idempotency: re-rollback → status='already_rolled_back', no error
 *  5. Applied txn → RAISE EXCEPTION (use refund flow instead)
 *  6. Invalid reason → RAISE EXCEPTION
 *
 * Per-test isolation: each test creates its own studio and project.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  type RollbackDepositApplicationArgs,
  type RollbackDepositApplicationResult,
  type InkosIdempotencyKey,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: rollback_deposit_application', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string

  beforeEach(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
  })

  afterEach(async () => {
    await cleanupStudio(studioId)
  })

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------

  async function insertProjectWithPool(poolInCents: number): Promise<string> {
    const projectId = randomUUID()
    const { error } = await sb.from('projects').insert({
      id: projectId,
      studio_id: studioId,
      name: `Test Project ${projectId.slice(0, 8)}`,
      deposit_pool_cents_in: poolInCents,
      deposit_pool_cents_applied: 0,
      deposit_pool_cents_available: poolInCents,
      status: 'active',
    })
    if (error) throw new Error(`insertProjectWithPool failed: ${error.message}`)
    return projectId
  }

  function makeIdempotencyKey(): InkosIdempotencyKey {
    return `inkos_apply_deposit_${randomUUID().replace(/-/g, '').slice(0, 32)}` as InkosIdempotencyKey
  }

  async function createPendingApplyTxn(
    projectId: string,
    drawCents: number = 20000,
  ): Promise<string> {
    const { data, error } = await sb.rpc(RPC.APPLY_DEPOSIT_TO_SESSION, {
      p_project_id: projectId,
      p_session_id: randomUUID(),
      p_draw_cents: drawCents,
      p_idempotency_key: makeIdempotencyKey(),
    })
    if (error) throw new Error(`createPendingApplyTxn failed: ${error.message}`)
    const result = data as { transaction_id: string }
    return result.transaction_id
  }

  async function verifyPoolState(
    projectId: string,
  ): Promise<{ available: number; applied: number }> {
    const { data } = await sb
      .from('projects')
      .select('deposit_pool_cents_available, deposit_pool_cents_applied')
      .eq('id', projectId)
      .single()

    return {
      available: (data as { deposit_pool_cents_available: number } | null)?.deposit_pool_cents_available ?? 0,
      applied: (data as { deposit_pool_cents_applied: number } | null)?.deposit_pool_cents_applied ?? 0,
    }
  }

  async function rollback(
    txnId: string,
    reason: RollbackDepositApplicationArgs['reason'],
  ): Promise<{ data: RollbackDepositApplicationResult | null; error: { message: string } | null }> {
    const { data, error } = await sb.rpc(RPC.ROLLBACK_DEPOSIT_APPLICATION, {
      p_transaction_id: txnId,
      p_reason: reason,
    })
    return { data: data as RollbackDepositApplicationResult | null, error }
  }

  it('payment_failed reason — pending_apply transitions to rolled_back, pool re-incremented', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await createPendingApplyTxn(projectId, 20000)

    // After apply: available=20000, applied=20000
    const before = await verifyPoolState(projectId)
    expect(before.available).toBe(20000)
    expect(before.applied).toBe(20000)

    const { data, error } = await rollback(txnId, 'payment_failed')
    expect(error).toBeNull()

    const result = data as RollbackDepositApplicationResult
    expect(result.transaction_id).toBe(txnId)
    expect(result.status).toBe('rolled_back')
    expect(result.pool_available_cents).toBe(40000)

    // Verify pool restored
    const after = await verifyPoolState(projectId)
    expect(after.available).toBe(40000)
    expect(after.applied).toBe(0)

    // Verify txn row status
    const { data: txnRow } = await sb
      .from('project_deposit_transactions')
      .select('status, rolled_back_at, rollback_reason')
      .eq('id', txnId)
      .single()

    expect(txnRow?.status).toBe('rolled_back')
    expect(txnRow?.rolled_back_at).toBeTruthy()
    expect(txnRow?.rollback_reason).toBe('payment_failed')
  })

  it('payment_canceled reason — pending_apply transitions to rolled_back, pool re-incremented', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await createPendingApplyTxn(projectId, 15000)

    const { data, error } = await rollback(txnId, 'payment_canceled')
    expect(error).toBeNull()

    const result = data as RollbackDepositApplicationResult
    expect(result.status).toBe('rolled_back')
    expect(result.pool_available_cents).toBe(40000)

    const after = await verifyPoolState(projectId)
    expect(after.available).toBe(40000)
  })

  it('reaper_timeout reason — pending_apply transitions to rolled_back, pool re-incremented', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await createPendingApplyTxn(projectId, 30000)

    const { data, error } = await rollback(txnId, 'reaper_timeout')
    expect(error).toBeNull()

    const result = data as RollbackDepositApplicationResult
    expect(result.status).toBe('rolled_back')
    expect(result.pool_available_cents).toBe(40000)
  })

  it('idempotency — re-rollback of already-rolled-back txn returns status=already_rolled_back', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await createPendingApplyTxn(projectId)

    // First rollback
    const { error: e1 } = await rollback(txnId, 'payment_failed')
    expect(e1).toBeNull()

    // Second rollback — idempotent
    const { data: second, error: e2 } = await rollback(txnId, 'payment_failed')
    expect(e2).toBeNull()
    const result = second as RollbackDepositApplicationResult
    expect(result.status).toBe('already_rolled_back')
    expect(result.transaction_id).toBe(txnId)
    // Pool must not be double-credited
    const pool = await verifyPoolState(projectId)
    expect(pool.available).toBe(40000)
  })

  it('applied txn — cannot rollback a confirmed txn; raises exception', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await createPendingApplyTxn(projectId)

    // Confirm the txn
    const { error: confirmErr } = await sb.rpc(RPC.CONFIRM_DEPOSIT_APPLICATION, {
      p_transaction_id: txnId,
      p_payment_intent_id: `pi_test_${randomUUID().replace(/-/g, '').slice(0, 24)}`,
    })
    expect(confirmErr).toBeNull()

    // Try to rollback an applied txn — must fail
    const { error } = await rollback(txnId, 'payment_failed')
    expect(error).not.toBeNull()
    expect(
      error?.code === 'P0001' ||
      error?.message?.toLowerCase().includes('applied') ||
      error?.message?.toLowerCase().includes('cannot rollback') ||
      error?.message?.toLowerCase().includes('refund'),
    ).toBe(true)
  })

  it('invalid reason — raises exception', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await createPendingApplyTxn(projectId)

    const { error } = await sb.rpc(RPC.ROLLBACK_DEPOSIT_APPLICATION, {
      p_transaction_id: txnId,
      p_reason: 'INVALID_REASON_XYZ', // not in the valid enum
    })

    expect(error).not.toBeNull()
  })
})

/**
 * RPC contract tests: release_deposit_from_session
 *
 * Coverage (7 tests — DB-gated via describe.skipIf):
 *  1. Happy full release: applied $200 draw → release $200 → pool back to full
 *  2. Happy partial release: $200 applied, release $100 → pool +$100, total_released=$100
 *  3. Multiple partial releases: $200 applied, release $50 then $100 → total_released=$150
 *  4. Bounds exceed: try release $300 against $200 parent → RAISE EXCEPTION
 *  5. Bounds exceed via accumulation: $200 applied, $100 released, try $150 more → exception
 *  6. Idempotency: same idempotency_key → returns same release row, no double-credit
 *  7. Parent in pending_apply → RAISE EXCEPTION (cannot release pre-confirmation)
 *
 * Per-test isolation: each test creates its own studio and project.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  type ReleaseDepositFromSessionResult,
  type InkosIdempotencyKey,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: release_deposit_from_session', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string

  beforeEach(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
  })

  afterEach(async () => {
    await cleanupStudio(studioId)
  })

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------

  async function insertProjectWithPool(poolInCents: number): Promise<string> {
    const projectId = randomUUID()
    const { error } = await sb.from('projects').insert({
      id: projectId,
      studio_id: studioId,
      name: `Test Project ${projectId.slice(0, 8)}`,
      deposit_pool_cents_in: poolInCents,
      deposit_pool_cents_applied: 0,
      deposit_pool_cents_available: poolInCents,
      status: 'active',
    })
    if (error) throw new Error(`insertProjectWithPool failed: ${error.message}`)
    return projectId
  }

  function makeApplyKey(): InkosIdempotencyKey {
    return `inkos_apply_deposit_${randomUUID().replace(/-/g, '').slice(0, 32)}` as InkosIdempotencyKey
  }

  function makeReleaseKey(): InkosIdempotencyKey {
    return `inkos_release_${randomUUID().replace(/-/g, '').slice(0, 32)}` as InkosIdempotencyKey
  }

  function makeRefundId(): string {
    return `re_test_${randomUUID().replace(/-/g, '').slice(0, 24)}`
  }

  async function applyAndConfirmTxn(
    projectId: string,
    drawCents: number,
  ): Promise<string> {
    const { data: applyData, error: applyErr } = await sb.rpc(RPC.APPLY_DEPOSIT_TO_SESSION, {
      p_project_id: projectId,
      p_session_id: randomUUID(),
      p_draw_cents: drawCents,
      p_idempotency_key: makeApplyKey(),
    })
    if (applyErr) throw new Error(`applyTxn failed: ${applyErr.message}`)
    const txnId = (applyData as { transaction_id: string }).transaction_id

    const { error: confirmErr } = await sb.rpc(RPC.CONFIRM_DEPOSIT_APPLICATION, {
      p_transaction_id: txnId,
      p_payment_intent_id: `pi_test_${randomUUID().replace(/-/g, '').slice(0, 24)}`,
    })
    if (confirmErr) throw new Error(`confirmTxn failed: ${confirmErr.message}`)

    return txnId
  }

  async function verifyPoolState(
    projectId: string,
  ): Promise<{ available: number; applied: number; total: number }> {
    const { data } = await sb
      .from('projects')
      .select('deposit_pool_cents_available, deposit_pool_cents_applied, deposit_pool_cents_in')
      .eq('id', projectId)
      .single()

    const row = data as {
      deposit_pool_cents_available: number
      deposit_pool_cents_applied: number
      deposit_pool_cents_in: number
    } | null
    return {
      available: row?.deposit_pool_cents_available ?? 0,
      applied: row?.deposit_pool_cents_applied ?? 0,
      total: row?.deposit_pool_cents_in ?? 0,
    }
  }

  async function release(
    txnId: string,
    releaseCents: number,
    idemKey?: InkosIdempotencyKey,
    refundId?: string,
  ): Promise<{ data: ReleaseDepositFromSessionResult | null; error: { message: string; code?: string } | null }> {
    const { data, error } = await sb.rpc(RPC.RELEASE_DEPOSIT_FROM_SESSION, {
      p_transaction_id: txnId,
      p_release_cents: releaseCents,
      p_idempotency_key: idemKey ?? makeReleaseKey(),
      p_refund_id: refundId ?? makeRefundId(),
    })
    return { data: data as ReleaseDepositFromSessionResult | null, error }
  }

  it('full release — applied $200 draw, release $200, pool fully restored', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await applyAndConfirmTxn(projectId, 20000)

    const { data, error } = await release(txnId, 20000)
    expect(error).toBeNull()

    const result = data as ReleaseDepositFromSessionResult
    expect(result.release_transaction_id).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/,
    )
    expect(result.pool_available_cents).toBe(40000)
    expect(result.total_released_cents).toBe(20000)

    const pool = await verifyPoolState(projectId)
    expect(pool.available).toBe(40000)
    expect(pool.applied).toBe(0)
  })

  it('partial release — $200 applied, release $100, pool grows by $100, total_released=$100', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await applyAndConfirmTxn(projectId, 20000)

    const { data, error } = await release(txnId, 10000)
    expect(error).toBeNull()

    const result = data as ReleaseDepositFromSessionResult
    expect(result.pool_available_cents).toBe(30000) // 40000 - 20000 + 10000
    expect(result.total_released_cents).toBe(10000)

    const pool = await verifyPoolState(projectId)
    expect(pool.available).toBe(30000)
    expect(pool.applied).toBe(10000) // still $100 applied, $100 released
  })

  it('multiple partial releases — $200 applied, release $50 then $100, total_released=$150', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await applyAndConfirmTxn(projectId, 20000)

    // First partial: $50
    const { error: e1 } = await release(txnId, 5000)
    expect(e1).toBeNull()

    // Second partial: $100
    const { data: second, error: e2 } = await release(txnId, 10000)
    expect(e2).toBeNull()

    const result = second as ReleaseDepositFromSessionResult
    expect(result.total_released_cents).toBe(15000) // $50 + $100 = $150
    // Pool was 20000 (40000-20000) → +5000 → +10000 = 35000
    expect(result.pool_available_cents).toBe(35000)
  })

  it('bounds exceed — try to release $300 against $200 draw raises exception', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await applyAndConfirmTxn(projectId, 20000)

    const { error } = await release(txnId, 30000) // $300 > $200 draw
    expect(error).not.toBeNull()
    expect(
      error?.code === 'P0001' ||
      error?.message?.toLowerCase().includes('exceed') ||
      error?.message?.toLowerCase().includes('cannot release') ||
      error?.message?.toLowerCase().includes('bounds'),
    ).toBe(true)
  })

  it('bounds exceed via accumulation — $200 applied, $100 already released, try $150 more raises exception', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await applyAndConfirmTxn(projectId, 20000)

    // Release $100
    const { error: e1 } = await release(txnId, 10000)
    expect(e1).toBeNull()

    // Try to release another $150 (would total $250 > $200 draw)
    const { error } = await release(txnId, 15000)
    expect(error).not.toBeNull()
    expect(
      error?.code === 'P0001' ||
      error?.message?.toLowerCase().includes('exceed') ||
      error?.message?.toLowerCase().includes('bounds'),
    ).toBe(true)
  })

  it('idempotency — same idempotency_key returns same release row, no double-credit', async () => {
    const projectId = await insertProjectWithPool(40000)
    const txnId = await applyAndConfirmTxn(projectId, 20000)
    const idemKey = makeReleaseKey()
    const refundId = makeRefundId()

    const { data: first, error: e1 } = await release(txnId, 10000, idemKey, refundId)
    expect(e1).toBeNull()
    const firstResult = first as ReleaseDepositFromSessionResult

    const { data: second, error: e2 } = await release(txnId, 10000, idemKey, refundId)
    expect(e2).toBeNull()
    const secondResult = second as ReleaseDepositFromSessionResult

    // Same release_transaction_id returned
    expect(secondResult.release_transaction_id).toBe(firstResult.release_transaction_id)
    // Pool not double-credited
    const pool = await verifyPoolState(projectId)
    expect(pool.available).toBe(30000) // 40000 - 20000 + 10000 (only once)
  })

  it('parent in pending_apply — cannot release pre-confirmation raises exception', async () => {
    const projectId = await insertProjectWithPool(40000)

    // Apply but do NOT confirm
    const { data: applyData, error: applyErr } = await sb.rpc(RPC.APPLY_DEPOSIT_TO_SESSION, {
      p_project_id: projectId,
      p_session_id: randomUUID(),
      p_draw_cents: 20000,
      p_idempotency_key: makeApplyKey(),
    })
    expect(applyErr).toBeNull()
    const txnId = (applyData as { transaction_id: string }).transaction_id

    // Try to release a pending_apply txn (not yet confirmed)
    const { error } = await release(txnId, 20000)
    expect(error).not.toBeNull()
    expect(
      error?.code === 'P0001' ||
      error?.message?.toLowerCase().includes('pending') ||
      error?.message?.toLowerCase().includes('applied') ||
      error?.message?.toLowerCase().includes('cannot release'),
    ).toBe(true)
  })
})

/**
 * Unit tests: lib/payments/capability-gate
 *
 * Coverage (7 tests — no DB needed, supabase.rpc mocked):
 *  1. requireStudioL2Enabled — RPC returns enabled=true → returns { accountId }
 *  2. RPC returns enabled=false, reason='no_connected_account' → throws CapabilityGateError, httpStatus=403
 *  3. RPC returns onboarding_pending → throws with mapped userMessage
 *  4. RPC returns onboarding_restricted → throws with mapped userMessage
 *  5. RPC returns onboarding_rejected → throws with mapped userMessage
 *  6. RPC returns charges_disabled → throws with mapped userMessage
 *  7. RPC returns enabled=true but account_id=null → throws CapabilityGateError httpStatus=500
 *  8. capabilityGateErrorResponse — produces 403 Response with { error, reason, message } shape
 *
 * All tests run unconditionally — no DB required.
 */

import { describe, it, expect, vi } from 'vitest'
import type { SupabaseClient } from '@supabase/supabase-js'
import {
  requireStudioL2Enabled,
  CapabilityGateError,
  capabilityGateErrorResponse,
} from '@/lib/payments/capability-gate'
import type { StudioL2PaymentsEnabledResult } from '@/lib/payments/contracts'

// ---------------------------------------------------------------------------
// Factory: build a minimal supabase mock that controls rpc() output
// ---------------------------------------------------------------------------

function makeSupabaseMock(
  result: StudioL2PaymentsEnabledResult | null,
  rpcError: { message: string } | null = null,
): SupabaseClient {
  return {
    rpc: vi.fn().mockResolvedValue({ data: result, error: rpcError }),
  } as unknown as SupabaseClient
}

const STUDIO_ID = '11111111-1111-4111-8111-000000000001'

// ---------------------------------------------------------------------------
// requireStudioL2Enabled
// ---------------------------------------------------------------------------

describe('requireStudioL2Enabled', () => {
  it('enabled=true + account_id present → returns { accountId }', async () => {
    const sb = makeSupabaseMock({
      enabled: true,
      reason: null,
      account_id: 'acct_test_abc123',
      onboarding_status: 'active',
    })

    const result = await requireStudioL2Enabled(sb, STUDIO_ID)
    expect(result.accountId).toBe('acct_test_abc123')
  })

  it('enabled=false, reason=no_connected_account → throws CapabilityGateError httpStatus=403', async () => {
    const sb = makeSupabaseMock({
      enabled: false,
      reason: 'no_connected_account',
      account_id: null,
      onboarding_status: null,
    })

    await expect(requireStudioL2Enabled(sb, STUDIO_ID)).rejects.toThrow(CapabilityGateError)

    try {
      await requireStudioL2Enabled(sb, STUDIO_ID)
    } catch (err) {
      expect(err).toBeInstanceOf(CapabilityGateError)
      const gate = err as CapabilityGateError
      expect(gate.reason).toBe('no_connected_account')
      expect(gate.httpStatus).toBe(403)
      expect(gate.userMessage).toContain('payment')
    }
  })

  it('enabled=false, reason=onboarding_pending → throws CapabilityGateError with mapped message', async () => {
    const sb = makeSupabaseMock({
      enabled: false,
      reason: 'onboarding_pending',
      account_id: 'acct_pending_123',
      onboarding_status: 'pending',
    })

    try {
      await requireStudioL2Enabled(sb, STUDIO_ID)
      expect.fail('should have thrown')
    } catch (err) {
      expect(err).toBeInstanceOf(CapabilityGateError)
      const gate = err as CapabilityGateError
      expect(gate.reason).toBe('onboarding_pending')
      expect(gate.httpStatus).toBe(403)
      expect(gate.userMessage.length).toBeGreaterThan(0)
    }
  })

  it('enabled=false, reason=onboarding_restricted → throws CapabilityGateError with mapped message', async () => {
    const sb = makeSupabaseMock({
      enabled: false,
      reason: 'onboarding_restricted',
      account_id: 'acct_restricted_456',
      onboarding_status: 'restricted',
    })

    try {
      await requireStudioL2Enabled(sb, STUDIO_ID)
      expect.fail('should have thrown')
    } catch (err) {
      expect(err).toBeInstanceOf(CapabilityGateError)
      const gate = err as CapabilityGateError
      expect(gate.reason).toBe('onboarding_restricted')
      expect(gate.userMessage).toContain('document')
    }
  })

  it('enabled=false, reason=onboarding_rejected → throws CapabilityGateError with mapped message', async () => {
    const sb = makeSupabaseMock({
      enabled: false,
      reason: 'onboarding_rejected',
      account_id: 'acct_rejected_789',
      onboarding_status: 'rejected',
    })

    try {
      await requireStudioL2Enabled(sb, STUDIO_ID)
      expect.fail('should have thrown')
    } catch (err) {
      expect(err).toBeInstanceOf(CapabilityGateError)
      const gate = err as CapabilityGateError
      expect(gate.reason).toBe('onboarding_rejected')
      expect(gate.userMessage.length).toBeGreaterThan(0)
    }
  })

  it('enabled=false, reason=charges_disabled → throws CapabilityGateError with mapped message', async () => {
    const sb = makeSupabaseMock({
      enabled: false,
      reason: 'charges_disabled',
      account_id: 'acct_disabled_abc',
      onboarding_status: 'active',
    })

    try {
      await requireStudioL2Enabled(sb, STUDIO_ID)
      expect.fail('should have thrown')
    } catch (err) {
      expect(err).toBeInstanceOf(CapabilityGateError)
      const gate = err as CapabilityGateError
      expect(gate.reason).toBe('charges_disabled')
      expect(gate.userMessage).toContain('disabled')
    }
  })

  it('enabled=true but account_id=null → throws CapabilityGateError httpStatus=500', async () => {
    const sb = makeSupabaseMock({
      enabled: true,
      reason: null,
      account_id: null, // should not happen in practice — test the guard
      onboarding_status: 'active',
    })

    try {
      await requireStudioL2Enabled(sb, STUDIO_ID)
      expect.fail('should have thrown')
    } catch (err) {
      expect(err).toBeInstanceOf(CapabilityGateError)
      const gate = err as CapabilityGateError
      expect(gate.httpStatus).toBe(500)
      expect(gate.reason).toBe('account_id_missing')
    }
  })
})

// ---------------------------------------------------------------------------
// capabilityGateErrorResponse
// ---------------------------------------------------------------------------

describe('capabilityGateErrorResponse', () => {
  it('produces a Response with status=403 and { error, reason, message } body', async () => {
    const err = new CapabilityGateError(
      'no_connected_account',
      'Set up in-studio payments before charging clients.',
      403,
    )

    const res = capabilityGateErrorResponse(err)
    expect(res.status).toBe(403)

    const body = await res.json() as { error: string; reason: string; message: string }
    expect(body.error).toBe('capability_gate')
    expect(body.reason).toBe('no_connected_account')
    expect(body.message).toBe('Set up in-studio payments before charging clients.')
  })

  it('uses httpStatus from the error for non-403 cases', async () => {
    const err = new CapabilityGateError('account_id_missing', 'Incomplete account.', 500)
    const res = capabilityGateErrorResponse(err)
    expect(res.status).toBe(500)
  })
})

/**
 * Integration tests: lib/stripe/charges — createSessionPaymentIntent
 *
 * Stripe SDK mocked. Supabase client mocked.
 * All tests run unconditionally (no DB required).
 *
 * Coverage (11 tests):
 *  1. Happy path with deposit drawdown: capability gate passes, deposit applied, PI created, charge mirrored
 *  2. No drawdown: skips apply_deposit_to_session, PI amount = base + tip
 *  3. Capability gate fails: throws CapabilityGateError, no Stripe call made
 *  4. Country drift: throws CapabilityGateError reason='country_drift', no PI created
 *  5. Studio country missing: throws CapabilityGateError reason='country_missing'
 *  6. PI creation fails after deposit applied: ROLLBACK called automatically
 *  7. Banker's rounding: 67% on $100 → applicationFeeCents = 33
 *  8. Idempotency: same booking_id+session_id → same PI idempotency key
 *  9. Artist no connected account: full base used as effectiveApplicationFee
 * 10. INVARIANT 4: application_fee_amount always set (never undefined)
 * 11. INVARIANT 2: stripe.paymentIntents.create called with idempotencyKey option AND metadata.inkos_idempotency_key
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import type { SupabaseClient } from '@supabase/supabase-js'
import { cents, RPC } from '@/lib/payments/contracts'
import { CapabilityGateError } from '@/lib/payments/capability-gate'
import type {
  CreateSessionPaymentIntentArgs,
} from '@/lib/stripe/charges'

// ---------------------------------------------------------------------------
// Mock Stripe SDK
// ---------------------------------------------------------------------------

const mockPaymentIntentsCreate = vi.fn()

vi.mock('@/lib/stripe/client', () => ({
  getStripe: () => ({
    paymentIntents: {
      create: mockPaymentIntentsCreate,
    },
  }),
}))

// ---------------------------------------------------------------------------
// Mock capability gate
// ---------------------------------------------------------------------------

let mockCapabilityGateEnabled = true
let mockCapabilityGateError: CapabilityGateError | null = null

vi.mock('@/lib/payments/capability-gate', async (importOriginal) => {
  const original = await importOriginal<typeof import('@/lib/payments/capability-gate')>()
  return {
    ...original,
    requireStudioL2Enabled: vi.fn(async () => {
      if (mockCapabilityGateError) throw mockCapabilityGateError
      if (!mockCapabilityGateEnabled) {
        throw new original.CapabilityGateError('no_connected_account', 'Set up payments first.', 403)
      }
      return { accountId: 'acct_studio_test_123' }
    }),
  }
})

// ---------------------------------------------------------------------------
// Mock logger
// ---------------------------------------------------------------------------

vi.mock('@/lib/logger', () => ({
  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
}))

// ---------------------------------------------------------------------------
// Supabase mock factory
// ---------------------------------------------------------------------------

interface RpcCallMap {
  [key: string]: { data: unknown; error: null | { message: string } }
}

function makeSupabaseMock(opts: {
  rpcResponses?: RpcCallMap
  studioCountry?: string | null
  accountCountry?: string | null
  stripeChargeError?: { message: string } | null
}): SupabaseClient {
  const rpcResponses: RpcCallMap = opts.rpcResponses ?? {}

  // Default RPC mock — returns success unless overridden
  const rpcMock = vi.fn(async (fn: string) => {
    if (fn in rpcResponses) return rpcResponses[fn]
    // Default: APPLY returns a txn_id, ROLLBACK succeeds, STRIPE_CHARGE_RECORD succeeds
    if (fn === RPC.APPLY_DEPOSIT_TO_SESSION) {
      return {
        data: {
          transaction_id: 'txn-test-001',
          pool_in_cents: 40000,
          pool_applied_cents: 20000,
          pool_available_cents: 20000,
        },
        error: null,
      }
    }
    if (fn === RPC.ROLLBACK_DEPOSIT_APPLICATION) {
      return { data: { transaction_id: 'txn-test-001', status: 'rolled_back', pool_available_cents: 40000 }, error: null }
    }
    if (fn === RPC.STRIPE_CHARGE_RECORD) {
      return { data: { id: 'charge-row-001', created: true }, error: opts.stripeChargeError ? null : null }
    }
    return { data: null, error: null }
  })

  // from() mock for country alignment check
  const fromMock = vi.fn((table: string) => {
    if (table === 'studios') {
      return {
        select: vi.fn(() => ({
          eq: vi.fn(() => ({
            single: vi.fn(async () => ({
              data: { country: opts.studioCountry ?? 'US' },
              error: opts.studioCountry === undefined ? { message: 'Not found' } : null,
            })),
          })),
        })),
      }
    }
    if (table === 'stripe_connected_accounts') {
      return {
        select: vi.fn(() => ({
          eq: vi.fn(() => ({
            eq: vi.fn(() => ({
              single: vi.fn(async () => ({
                data: { country: opts.accountCountry ?? 'US' },
                error: opts.accountCountry === undefined ? { message: 'Not found' } : null,
              })),
            })),
          })),
        })),
      }
    }
    return { select: vi.fn(() => ({ eq: vi.fn(() => ({ single: vi.fn() })) })) }
  })

  return { rpc: rpcMock, from: fromMock } as unknown as SupabaseClient
}

