describe('createSessionPaymentIntent', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    mockCapabilityGateEnabled = true
    mockCapabilityGateError = null

    // Default PI mock — returns a succeeded PI
    mockPaymentIntentsCreate.mockResolvedValue({
      id: 'pi_test_mock_001',
