  it('happy path with deposit drawdown — capability gate passes, deposit applied, PI created, charge mirrored', async () => {
    const { createSessionPaymentIntent } = await import('@/lib/stripe/charges')
    const sb = makeSupabaseMock({})
    const args = makeArgs({ depositDrawdownCents: cents(5000) })

    const result = await createSessionPaymentIntent(sb, args)

    expect(result.paymentIntentId).toBe('pi_test_mock_001')
    expect(result.depositTransactionId).toBe('txn-test-001')
    expect(result.amountChargedCents).toBe(15000 + 500 - 5000) // base + tip - drawdown
    expect(mockPaymentIntentsCreate).toHaveBeenCalledOnce()

    // Verify APPLY_DEPOSIT_TO_SESSION was called
    const rpcCalls = (sb.rpc as ReturnType<typeof vi.fn>).mock.calls
    const applyCalls = rpcCalls.filter(([fn]: [string]) => fn === RPC.APPLY_DEPOSIT_TO_SESSION)
    expect(applyCalls).toHaveLength(1)
  })

  it('no drawdown — skips apply_deposit_to_session, PI amount = base + tip', async () => {
    const { createSessionPaymentIntent } = await import('@/lib/stripe/charges')
    const sb = makeSupabaseMock({})
    const args = makeArgs({ depositDrawdownCents: cents(0) })

    const result = await createSessionPaymentIntent(sb, args)

    expect(result.depositTransactionId).toBeNull()
    expect(result.amountChargedCents).toBe(15000 + 500) // base + tip

    const rpcCalls = (sb.rpc as ReturnType<typeof vi.fn>).mock.calls
    const applyCalls = rpcCalls.filter(([fn]: [string]) => fn === RPC.APPLY_DEPOSIT_TO_SESSION)
    expect(applyCalls).toHaveLength(0)
