    const args = makeArgs()

    await expect(createSessionPaymentIntent(sb, args)).rejects.toThrow(CapabilityGateError)
    expect(mockPaymentIntentsCreate).not.toHaveBeenCalled()
  })

  it('country drift — throws CapabilityGateError reason=country_drift, no PI created', async () => {
    const { createSessionPaymentIntent } = await import('@/lib/stripe/charges')
    // Studio says 'GB' but Stripe account is 'US'
    const sb = makeSupabaseMock({ studioCountry: 'GB', accountCountry: 'US' })
    const args = makeArgs()

    try {
      await createSessionPaymentIntent(sb, args)
      expect.fail('should have thrown')
    } catch (err) {
      expect(err).toBeInstanceOf(CapabilityGateError)
      const gate = err as CapabilityGateError
      expect(gate.reason).toBe('country_drift')
      expect(gate.httpStatus).toBe(422)
    }

    expect(mockPaymentIntentsCreate).not.toHaveBeenCalled()
  })

  it('studio country missing — throws CapabilityGateError reason=country_missing', async () => {
    const { createSessionPaymentIntent } = await import('@/lib/stripe/charges')
    const sb = makeSupabaseMock({ studioCountry: null, accountCountry: 'US' })
    const args = makeArgs()

    try {
      await createSessionPaymentIntent(sb, args)
      expect.fail('should have thrown')
    } catch (err) {
      expect(err).toBeInstanceOf(CapabilityGateError)
      const gate = err as CapabilityGateError
      expect(gate.reason).toBe('country_missing')
    }
  })

  it('PI creation fails after deposit applied — ROLLBACK called automatically', async () => {
    const { createSessionPaymentIntent } = await import('@/lib/stripe/charges')
