    // Studio gets 33% of $100 = $33.00 → applicationFeeCents = 3300
    expect(capturedArgs?.application_fee_amount).toBe(3300)
  })

  it('idempotency — same booking_id+session_id produces deterministic PI idempotency key', async () => {
    const { createSessionPaymentIntent } = await import('@/lib/stripe/charges')

    const capturedKeys: string[] = []
    mockPaymentIntentsCreate.mockImplementation(async (_, opts: { idempotencyKey?: string }) => {
