        currency: 'usd',
        metadata: {},
      }
    })

    const sb = makeSupabaseMock({})
    const args = makeArgs()

    await createSessionPaymentIntent(sb, args)
    vi.clearAllMocks()

    mockPaymentIntentsCreate.mockImplementation(async (_, opts: { idempotencyKey?: string }) => {
      capturedKeys.push(opts?.idempotencyKey ?? '')
      return {
        id: 'pi_test_003',
        client_secret: 'pi_test_003_secret',
        status: 'succeeded',
        amount: 15500,
        currency: 'usd',
        metadata: {},
      }
