    expect(capturedKeys[0]).toBe(capturedKeys[1])
    expect(capturedKeys[0]).toContain('inkos_')
  })

  it('artist no connected account — effectiveApplicationFee = full baseAmountCents', async () => {
    const { createSessionPaymentIntent } = await import('@/lib/stripe/charges')

    let capturedArgs: Parameters<typeof mockPaymentIntentsCreate>[0] | undefined
    mockPaymentIntentsCreate.mockImplementation(async (piArgs: Parameters<typeof mockPaymentIntentsCreate>[0]) => {
      capturedArgs = piArgs
      return {
        id: 'pi_test_004',
        client_secret: 'pi_test_004_secret',
        status: 'succeeded',
        amount: piArgs.amount,
        currency: 'usd',
        metadata: piArgs.metadata,
      }
    })

    const sb = makeSupabaseMock({})
    const args = makeArgs({
      artistConnectedAccountId: null, // no artist account
      baseAmountCents: cents(10000),
      tipAmountCents: cents(0),
    })

    await createSessionPaymentIntent(sb, args)

    // When artist has no account: studio keeps everything → effectiveApplicationFee = baseAmountCents
    expect(capturedArgs?.application_fee_amount).toBe(10000)
    // Destination should be studio account
    expect(capturedArgs?.transfer_data?.destination).toBe('acct_studio_test_123')
  })

  it('INVARIANT 4 — application_fee_amount is always set (never undefined)', async () => {
    const { createSessionPaymentIntent } = await import('@/lib/stripe/charges')

