    // INVARIANT 4: application_fee_amount must be defined and a positive integer
    expect(capturedArgs?.application_fee_amount).toBeDefined()
    expect(typeof capturedArgs?.application_fee_amount).toBe('number')
    expect(capturedArgs?.application_fee_amount).toBeGreaterThan(0)
  })

  it('INVARIANT 2 — Stripe PI called with idempotencyKey option AND metadata.inkos_idempotency_key', async () => {
    const { createSessionPaymentIntent } = await import('@/lib/stripe/charges')

    let capturedBody: Parameters<typeof mockPaymentIntentsCreate>[0] | undefined
    let capturedOpts: Parameters<typeof mockPaymentIntentsCreate>[1] | undefined
