function makeSupabaseMock(opts: {
  chargeRow?: ReturnType<typeof makeChargeRow> | null
  commissionSplitError?: { message: string } | null
  depositTxnRow?: { id: string; status: string } | null
  releaseError?: { message: string } | null
  statusUpdateError?: { message: string } | null
}): SupabaseClient {
  const {
    chargeRow = makeChargeRow(),
    commissionSplitError = null,
    depositTxnRow = { id: 'deposit-txn-001', status: 'applied' },
    releaseError = null,
    statusUpdateError = null,
  } = opts

  const rpcMock = vi.fn(async (fn: string) => {
    if (fn === RPC.COMMISSION_SPLIT_REVERSE) {
      if (commissionSplitError) return { data: null, error: commissionSplitError }
      return { data: { id: 'reversal-row-001' }, error: null }
    }
    if (fn === RPC.RELEASE_DEPOSIT_FROM_SESSION) {
      if (releaseError) return { data: null, error: releaseError }
      return {
        data: {
          release_transaction_id: 'release-txn-001',
          pool_available_cents: 40000,
          total_released_cents: 5000,
        },
        error: null,
      }
    }
    return { data: null, error: null }
  })

  const fromMock = vi.fn((table: string) => {
    if (table === 'stripe_charges') {
      let isSingleQuery = false
      const mockObj = {
        select: vi.fn(() => {
          isSingleQuery = true
          return mockObj
        }),
        eq: vi.fn(() => mockObj),
        update: vi.fn(() => mockObj),
        single: vi.fn(async () => ({
          data: chargeRow,
          error: chargeRow === null ? { message: 'Not found' } : null,
        })),
        // For status update (chained from .update().eq())
        then: undefined,
      }
      // Also handle the update path which uses a direct promise (no .single())
      const updateObj = {
        eq: vi.fn(() =>
          Promise.resolve({ data: null, error: statusUpdateError }),
        ),
      }
      return {
        select: vi.fn(() => ({
          eq: vi.fn(() => ({
            eq: vi.fn(() => mockObj),
            single: vi.fn(async () => ({
              data: chargeRow,
              error: chargeRow === null ? { message: 'Not found' } : null,
            })),
          })),
        })),
        update: vi.fn(() => updateObj),
      }
    }

    if (table === 'commission_splits') {
      return {
        select: vi.fn(() => ({
          eq: vi.fn(() => ({
            eq: vi.fn(() => ({
              order: vi.fn(() => ({
                limit: vi.fn(() => ({
                  maybeSingle: vi.fn(async () => ({
                    data: { id: 'split-001', stripe_transfer_id: 'tr_test_001' },
                    error: null,
                  })),
                })),
              })),
            })),
          })),
        })),
      }
    }

    if (table === 'project_deposit_transactions') {
      return {
        select: vi.fn(() => ({
          eq: vi.fn(() => ({
            eq: vi.fn(() => ({
              order: vi.fn(() => ({
                limit: vi.fn(() => ({
                  maybeSingle: vi.fn(async () => ({
                    data: depositTxnRow,
                    error: null,
                  })),
                })),
              })),
            })),
          })),
        })),
      }
    }

    return { select: vi.fn() }
  })

  return { rpc: rpcMock, from: fromMock } as unknown as SupabaseClient
}

