    const sb = makeSupabaseMock({})

    const result = await refundCharge(sb, makeRefundArgs({ refundCents: cents(15000) }))

    expect(result.refundId).toBe('re_test_mock_001')
    expect(result.status).toBe('succeeded')
    expect(result.amountRefundedCents).toBe(15000)
    expect(result.commissionReversalId).toBe('reversal-row-001')
    expect(result.poolReleaseTransactionId).toBe('release-txn-001')

    // Verify Stripe was called with INVARIANT 5 flags
    const stripeCall = mockRefundsCreate.mock.calls[0]
    expect(stripeCall[0].reverse_transfer).toBe(true)
    expect(stripeCall[0].refund_application_fee).toBe(true)

    // Verify commission split reverse was called
    const rpcCalls = (sb.rpc as ReturnType<typeof vi.fn>).mock.calls
    const reversalCalls = rpcCalls.filter(([fn]: [string]) => fn === RPC.COMMISSION_SPLIT_REVERSE)
    expect(reversalCalls).toHaveLength(1)

    // Verify deposit release was called
    const releaseCalls = rpcCalls.filter(([fn]: [string]) => fn === RPC.RELEASE_DEPOSIT_FROM_SESSION)
    expect(releaseCalls).toHaveLength(1)
  })

  it('partial refund — status=partially_refunded', async () => {
