    // Amount should be partial
    expect(result.amountRefundedCents).toBe(7500)
    // Full refund check: 7500 !== 15000 → partially_refunded
    // Verify the update call was made (status update checked via mock)
    expect(result.refundId).toBe('re_test_partial_001')
  })

  it('INVARIANT 5 — reverse_transfer: true AND refund_application_fee: true are ALWAYS set', async () => {
    const { refundCharge } = await import('@/lib/stripe/refunds')
    const sb = makeSupabaseMock({})

    await refundCharge(sb, makeRefundArgs())

    expect(mockRefundsCreate).toHaveBeenCalledOnce()
    const [body] = mockRefundsCreate.mock.calls[0] as [Record<string, unknown>]

    // Both flags must be explicitly true — not truthy, literally true
    expect(body['reverse_transfer']).toBe(true)
    expect(body['refund_application_fee']).toBe(true)
  })

  it('refund > charge amount — throws before Stripe call', async () => {
