    const sb = makeSupabaseMock({})

    await expect(
      refundCharge(sb, makeRefundArgs({ refundCents: cents(99999) })),
    ).rejects.toThrow(/exceeds charge amount/)

    expect(mockRefundsCreate).not.toHaveBeenCalled()
  })

  it('refund <= 0 — throws before Stripe call', async () => {
    const { refundCharge } = await import('@/lib/stripe/refunds')
    const sb = makeSupabaseMock({})

    await expect(
      refundCharge(sb, makeRefundArgs({ refundCents: cents(0) })),
    ).rejects.toThrow(/invalid refund amount/)

    expect(mockRefundsCreate).not.toHaveBeenCalled()
  })

  it('capability gate fails — throws CapabilityGateError before Stripe call', async () => {
