    mockGateEnabled = false

    const sb = makeSupabaseMock({})
    await expect(refundCharge(sb, makeRefundArgs())).rejects.toThrow(CapabilityGateError)
    expect(mockRefundsCreate).not.toHaveBeenCalled()
  })

  it('no pool drawdown — deposit_drawdown_cents=0 skips release_deposit_from_session', async () => {
    const { refundCharge } = await import('@/lib/stripe/refunds')
    const sb = makeSupabaseMock({
      chargeRow: makeChargeRow({ deposit_drawdown_cents: 0 }),
    })

    const result = await refundCharge(sb, makeRefundArgs({ refundCents: cents(15000) }))

    expect(result.poolReleaseTransactionId).toBeNull()

    const rpcCalls = (sb.rpc as ReturnType<typeof vi.fn>).mock.calls
    const releaseCalls = rpcCalls.filter(([fn]: [string]) => fn === RPC.RELEASE_DEPOSIT_FROM_SESSION)
    expect(releaseCalls).toHaveLength(0)
  })

  it('commission reversal failure — logs CRITICAL but refund still completes', async () => {
    const { refundCharge } = await import('@/lib/stripe/refunds')
    const sb = makeSupabaseMock({
      commissionSplitError: { message: 'DB constraint violation' },
    })

    // Should NOT throw — commission reversal failure is non-fatal after Stripe refund succeeds
    const result = await refundCharge(sb, makeRefundArgs())

    expect(result.refundId).toBe('re_test_mock_001')
    // Commission reversal ID is null when the RPC failed
    expect(result.commissionReversalId).toBeNull()
    // Logger.error should have been called with CRITICAL message
    expect(mockLoggerError).toHaveBeenCalledWith(
      expect.objectContaining({ refund_id: 're_test_mock_001' }),
      expect.stringContaining('CRITICAL'),
    )
  })

  it('idempotency — same logical refund retry produces same Stripe idempotency key', async () => {
    const { refundCharge } = await import('@/lib/stripe/refunds')

    const capturedKeys: string[] = []
    mockRefundsCreate.mockImplementation(async (_, opts: { idempotencyKey?: string }) => {
      capturedKeys.push(opts?.idempotencyKey ?? '')
      return { id: 're_test_idem_001', status: 'succeeded', amount: 15000, transfer_reversal: null }
    })

    const sb1 = makeSupabaseMock({})
    const sb2 = makeSupabaseMock({})
    const args = makeRefundArgs()

    await refundCharge(sb1, args)
    await refundCharge(sb2, args)

    // Same args → same idempotency key on Stripe
    expect(capturedKeys[0]).toBe(capturedKeys[1])
    expect(capturedKeys[0]).toContain('inkos_')
  })
})

