/**
 * Integration tests: SAGA paths in lib/payments/process-stripe-event
 *
 * Tests S16 Track D additions: deposit SAGA RPC dispatch on PaymentIntent lifecycle events.
 * Supabase mocked. All tests run unconditionally.
 *
 * Coverage (7 tests):
 *  1. payment_intent.succeeded WITH deposit_transaction_id metadata → calls CONFIRM_DEPOSIT_APPLICATION + COMMISSION_SPLIT_RECORD
 *  2. payment_intent.succeeded WITHOUT deposit_transaction_id → skips CONFIRM, still calls STRIPE_CHARGE_UPDATE_STATUS
 *  3. payment_intent.payment_failed WITH deposit_transaction_id → calls ROLLBACK with reason='payment_failed'
 *  4. payment_intent.canceled WITH deposit_transaction_id → calls ROLLBACK with reason='payment_canceled'
 *  5. charge.refunded → updates stripe_charges.status (full=refunded vs partial=partially_refunded)
 *  6. CONFIRM RPC failure → throws (BullMQ retries)
 *  7. ROLLBACK RPC failure → throws
 *
 * NOTE: The S16 Track D implementation adds SAGA-aware branches to handlePaymentIntentStatusChange
 * and a new charge.refunded handler. These tests validate the intended behavior described in
 * contracts.ts and the sprint plan. If process-stripe-event.ts has not yet been updated for S16,
 * some tests will fail — that is intentional (TDD: tests define the contract before implementation).
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { RPC } from '@/lib/payments/contracts'
import type { StripeEventLike, SupabaseServiceClient } from '@/lib/payments/process-stripe-event'

