describe('processStripeEvent — S16 SAGA paths', () => {
  let processStripeEvent: (event: StripeEventLike, supabase: SupabaseServiceClient) => Promise<void>

  beforeEach(async () => {
    vi.clearAllMocks()
    // Re-import fresh each test to pick up vi.fn() state resets
    const mod = await import('@/lib/payments/process-stripe-event')
    processStripeEvent = mod.processStripeEvent
  })

  it('payment_intent.succeeded WITH deposit_transaction_id → CONFIRM_DEPOSIT_APPLICATION called + STRIPE_CHARGE_UPDATE_STATUS', async () => {
    const calledRpcs: string[] = []

