  studioCountry?: string | null
  accountCountry?: string | null
  stripeChargeError?: { message: string } | null
}): SupabaseClient {
  const rpcResponses: RpcCallMap = opts.rpcResponses ?? {}

  // Default RPC mock — returns success unless overridden
  const rpcMock = vi.fn(async (fn: string) => {
    if (fn in rpcResponses) return rpcResponses[fn]
    // Default: APPLY returns a txn_id, ROLLBACK succeeds, STRIPE_CHARGE_RECORD succeeds
    if (fn === RPC.APPLY_DEPOSIT_TO_SESSION) {
      return {
        data: {
