// ---------------------------------------------------------------------------
// Supabase mock factory
// ---------------------------------------------------------------------------

interface RpcCallMap {
  [key: string]: { data: unknown; error: null | { message: string } }
}

/**
 * Build a deeply-nested Supabase mock that correctly handles the chained
 * query builder pattern used by charges.ts:
 *
 *   studios:                  .from().select().eq().single()
 *   stripe_connected_accounts: .from().select().eq().eq().single()
 */
function makeSupabaseMock(opts: {
  rpcResponses?: RpcCallMap
  studioCountry?: string | null
  accountCountry?: string | null
  stripeChargeError?: { message: string } | null
}): SupabaseClient {
  const rpcResponses: RpcCallMap = opts.rpcResponses ?? {}

  // Default RPC mock — returns success unless overridden
  const rpcMock = vi.fn(async (fn: string) => {
    if (fn in rpcResponses) return rpcResponses[fn]
    if (fn === RPC.APPLY_DEPOSIT_TO_SESSION) {
      return {
        data: {
          transaction_id: 'txn-test-001',
          pool_in_cents: 40000,
          pool_applied_cents: 20000,
          pool_available_cents: 20000,
        },
        error: null,
      }
    }
    if (fn === RPC.ROLLBACK_DEPOSIT_APPLICATION) {
      return { data: { transaction_id: 'txn-test-001', status: 'rolled_back', pool_available_cents: 40000 }, error: null }
    }
    if (fn === RPC.STRIPE_CHARGE_RECORD) {
      return { data: { id: 'charge-row-001', created: true }, error: null }
    }
    return { data: null, error: null }
  })

  // Inline terminal factory — returns a consistent single() responder
  function makeSingle<T>(data: T, error: { message: string } | null = null) {
    return { single: vi.fn(async () => ({ data, error })) }
  }

  // from() mock for country alignment check used in ensureCountryAligned()
  const fromMock = vi.fn((table: string) => {
    if (table === 'studios') {
      // .select('country').eq('id', studioId).single()
      const studioData = opts.studioCountry !== undefined ? { country: opts.studioCountry } : null
      const studioError = opts.studioCountry === undefined ? { message: 'Not found' } : null
      return {
        select: vi.fn(() => ({
          eq: vi.fn(() => makeSingle(studioData, studioError)),
        })),
      }
    }
    if (table === 'stripe_connected_accounts') {
      // .select('country').eq('studio_id', …).eq('type','studio').single()
      const accData = opts.accountCountry !== undefined ? { country: opts.accountCountry ?? 'US' } : null
      const accError = opts.accountCountry === undefined ? { message: 'Not found' } : null
      return {
        select: vi.fn(() => ({
          eq: vi.fn(() => ({
            eq: vi.fn(() => makeSingle(accData, accError)),
          })),
        })),
      }
    }
    // Fallback for any other table
    return {
      select: vi.fn(() => ({
        eq: vi.fn(() => ({
          eq: vi.fn(() => ({ single: vi.fn(async () => ({ data: null, error: null })) })),
          single: vi.fn(async () => ({ data: null, error: null })),
        })),
      })),
    }
  })

  return { rpc: rpcMock, from: fromMock } as unknown as SupabaseClient
}

