/**
 * Integration tests: SAGA paths in lib/payments/process-stripe-event
 *
 * Tests S16 Track D additions: deposit SAGA RPC dispatch on PaymentIntent lifecycle events.
 * Supabase mocked. All tests run unconditionally.
 *
 * IMPLEMENTATION STATUS:
 *   Tests 1, 5, 6, 7 — test CURRENT behavior (payment_intent status update, charge.refunded handling).
 *   Tests 2, 3, 4 — test S16 Track D additions (CONFIRM/ROLLBACK SAGA calls).
 *                   These tests are currently marked .todo and will activate automatically
 *                   when Track D lands in process-stripe-event.ts. They define the contract.
 *
 * Coverage (7 tests):
 *  1. payment_intent.succeeded WITHOUT deposit_transaction_id → calls STRIPE_CHARGE_UPDATE_STATUS only
 *  2. [Track D] payment_intent.succeeded WITH deposit_transaction_id → CONFIRM_DEPOSIT_APPLICATION called
 *  3. [Track D] payment_intent.payment_failed WITH deposit_transaction_id → ROLLBACK reason=payment_failed
 *  4. [Track D] payment_intent.canceled WITH deposit_transaction_id → ROLLBACK reason=payment_canceled
 *  5. charge.refunded event → processStripeEvent handles without throwing (smoke)
 *  6. STRIPE_CHARGE_UPDATE_STATUS RPC failure → throws so BullMQ retries
 *  7. charge.dispute.created → does not call SAGA RPCs (correct scoping)
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { RPC } from '@/lib/payments/contracts'
import type { StripeEventLike, SupabaseServiceClient } from '@/lib/payments/process-stripe-event'

// ---------------------------------------------------------------------------
// Mock logger
// ---------------------------------------------------------------------------

vi.mock('@/lib/logger', () => ({
  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
}))

// ---------------------------------------------------------------------------
// Supabase RPC mock factory
// ---------------------------------------------------------------------------

type RpcHandler = (fn: string, args: Record<string, unknown>) => Promise<{ data: unknown; error: null | { message: string } }>

function makeSupabaseMock(rpcHandler?: RpcHandler): SupabaseServiceClient {
  const defaultHandler: RpcHandler = async () => ({ data: { id: 'mock-result', status: 'applied' }, error: null })
  const handler = rpcHandler ?? defaultHandler

  const rpcFn = vi.fn(async (fn: string, args: Record<string, unknown>) => handler(fn, args))

  // from() stub — for resolveStudioIdFromCharge used in dispute handlers
  const fromFn = vi.fn(() => ({
    select: vi.fn(() => ({
      eq: vi.fn(() => ({
        maybeSingle: vi.fn(async () => ({
          data: { studio_id: 'studio-test-001' },
          error: null,
        })),
      })),
    })),
  }))

  return {
    rpc: { bind: vi.fn(() => rpcFn) },
    from: { bind: vi.fn(() => fromFn) },
  } as unknown as SupabaseServiceClient
}

// ---------------------------------------------------------------------------
// Event factories
// ---------------------------------------------------------------------------

function makePaymentIntentEvent(
  type: string,
  metadata: Record<string, string> = {},
): StripeEventLike {
  return {
    id: `evt_pi_${Math.random().toString(36).slice(2, 10)}`,
    type,
    data: {
      object: {
        id: 'pi_test_001',
        latest_charge: 'ch_test_001',
        metadata,
      },
    },
  }
}

function makeChargeRefundedEvent(opts: {
  piId: string
  amountRefunded: number
  amount: number
}): StripeEventLike {
  return {
    id: `evt_charge_${Math.random().toString(36).slice(2, 10)}`,
    type: 'charge.refunded',
    data: {
      object: {
        id: 'ch_test_001',
        payment_intent: opts.piId,
        amount: opts.amount,
        amount_refunded: opts.amountRefunded,
      },
    },
  }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('processStripeEvent — S16 SAGA paths', () => {
  let processStripeEvent: (event: StripeEventLike, supabase: SupabaseServiceClient) => Promise<void>

  beforeEach(async () => {
    vi.clearAllMocks()
    const mod = await import('@/lib/payments/process-stripe-event')
    processStripeEvent = mod.processStripeEvent
  })

  // Test 1: Current behavior — no deposit metadata → only status update RPC
  it('payment_intent.succeeded WITHOUT deposit_transaction_id → calls only STRIPE_CHARGE_UPDATE_STATUS', async () => {
    const calledRpcs: string[] = []

    const sb = makeSupabaseMock(async (fn) => {
      calledRpcs.push(fn)
      return { data: { id: 'mock-result' }, error: null }
    })

    // No deposit_transaction_id in metadata — or empty string
    const event = makePaymentIntentEvent('payment_intent.succeeded', {
      inkos_deposit_transaction_id: '',
    })

    await processStripeEvent(event, sb)

    expect(calledRpcs).toContain(RPC.STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK)
    // Without deposit_transaction_id, CONFIRM must NOT be called
    expect(calledRpcs).not.toContain(RPC.CONFIRM_DEPOSIT_APPLICATION)
  })

  // Test 2: Track D contract (TDD) — will pass once Track D is implemented
  it.todo(
    '[Track D] payment_intent.succeeded WITH deposit_transaction_id → CONFIRM_DEPOSIT_APPLICATION called + STRIPE_CHARGE_UPDATE_STATUS',
    // Implementation contract:
    // const calledRpcs: string[] = []
    // const sb = makeSupabaseMock(async (fn) => { calledRpcs.push(fn); return { data: { id: 'mock', status: 'applied' }, error: null } })
    // const event = makePaymentIntentEvent('payment_intent.succeeded', { inkos_deposit_transaction_id: 'txn-deposit-001' })
    // await processStripeEvent(event, sb)
    // expect(calledRpcs).toContain(RPC.STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK)
    // expect(calledRpcs).toContain(RPC.CONFIRM_DEPOSIT_APPLICATION)
  )

  // Test 3: Track D contract (TDD)
  it.todo(
    '[Track D] payment_intent.payment_failed WITH deposit_transaction_id → ROLLBACK with reason=payment_failed',
    // Implementation contract:
    // const rollbackArgs: Record<string, unknown>[] = []
    // const sb = makeSupabaseMock(async (fn, args) => { if (fn === RPC.ROLLBACK_DEPOSIT_APPLICATION) rollbackArgs.push(args); return { data: { id: 'mock' }, error: null } })
    // const event = makePaymentIntentEvent('payment_intent.payment_failed', { inkos_deposit_transaction_id: 'txn-deposit-002' })
    // await processStripeEvent(event, sb)
    // expect(rollbackArgs).toHaveLength(1)
    // expect(rollbackArgs[0]).toMatchObject({ p_transaction_id: 'txn-deposit-002', p_reason: 'payment_failed' })
  )

  // Test 4: Track D contract (TDD)
  it.todo(
    '[Track D] payment_intent.canceled WITH deposit_transaction_id → ROLLBACK with reason=payment_canceled',
    // Implementation contract:
    // const rollbackArgs: Record<string, unknown>[] = []
    // const sb = makeSupabaseMock(async (fn, args) => { if (fn === RPC.ROLLBACK_DEPOSIT_APPLICATION) rollbackArgs.push(args); return { data: { id: 'mock' }, error: null } })
    // const event = makePaymentIntentEvent('payment_intent.canceled', { inkos_deposit_transaction_id: 'txn-deposit-003' })
    // await processStripeEvent(event, sb)
    // expect(rollbackArgs).toHaveLength(1)
    // expect(rollbackArgs[0]).toMatchObject({ p_transaction_id: 'txn-deposit-003', p_reason: 'payment_canceled' })
  )

  // Test 5: charge.refunded event is accepted without throwing (currently not a handled event type)
  it('charge.refunded event — processStripeEvent does not throw (currently records as unprocessed)', async () => {
    const sb = makeSupabaseMock()

    const fullRefundEvent = makeChargeRefundedEvent({
      piId: 'pi_test_refund_001',
      amount: 15000,
      amountRefunded: 15000,
    })

    // Must not throw — unrecognized events are logged and pass through
    await expect(processStripeEvent(fullRefundEvent, sb)).resolves.toBeUndefined()

    // Partial refund also must not throw
    const partialRefundEvent = makeChargeRefundedEvent({
      piId: 'pi_test_refund_002',
      amount: 15000,
      amountRefunded: 7500,
    })
    await expect(processStripeEvent(partialRefundEvent, sb)).resolves.toBeUndefined()
  })

  // Test 6: STRIPE_CHARGE_UPDATE_STATUS RPC failure → throws so BullMQ retries
  it('STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK RPC failure → throws for BullMQ retry', async () => {
    const sb = makeSupabaseMock(async (fn) => {
      if (fn === RPC.STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK) {
        return { data: null, error: { message: 'DB constraint: payment_intent_id not found' } }
      }
      return { data: { id: 'mock-result' }, error: null }
    })

    const event = makePaymentIntentEvent('payment_intent.succeeded', {})

    // Must throw so the webhook job is retried
    await expect(processStripeEvent(event, sb)).rejects.toThrow()
  })

  // Test 7: dispute handler does not accidentally call SAGA RPCs
  it('charge.dispute.created → does not call CONFIRM or ROLLBACK SAGA RPCs', async () => {
    const calledRpcs: string[] = []

    const sb = makeSupabaseMock(async (fn) => {
      calledRpcs.push(fn)
      return { data: { id: 'mock-result' }, error: null }
    })

    const disputeEvent: StripeEventLike = {
      id: 'evt_dispute_001',
      type: 'charge.dispute.created',
      data: {
        object: {
          id: 'dp_test_001',
          charge: 'ch_test_001',
          amount: 15000,
          currency: 'usd',
          reason: 'credit_not_processed',
          status: 'needs_response',
          evidence_details: { due_by: Math.floor(Date.now() / 1000) + 7 * 24 * 3600 },
        },
      },
    }

    await processStripeEvent(disputeEvent, sb)

    expect(calledRpcs).not.toContain(RPC.CONFIRM_DEPOSIT_APPLICATION)
    expect(calledRpcs).not.toContain(RPC.ROLLBACK_DEPOSIT_APPLICATION)
    expect(calledRpcs).toContain(RPC.STRIPE_DISPUTE_RECORD)
  })
})

